package com.example.task.service;
import com.example.task.model.Task;import org.springframework.amqp.rabbit.core.RabbitTemplate;import org.springframework.beans.factory.ObjectProvider;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import org.springframework.transaction.support.*;import java.util.*;
@Component public class TaskEventPublisher {private final RabbitTemplate rabbit;private final boolean enabled;public TaskEventPublisher(ObjectProvider<RabbitTemplate> p,@Value("${task.events.enabled:false}")boolean e){rabbit=p.getIfAvailable();enabled=e;}
 public void publish(String action,Task t,String actor){if(!enabled||rabbit==null)return;String eventId=UUID.randomUUID().toString();Map<String,Object> event=new LinkedHashMap<>();event.put("eventId",eventId);event.put("type","TASK_"+action.toUpperCase());event.put("taskId",t.getId());event.put("workspaceId",t.getWorkspaceId());event.put("projectId",t.getProjectId());event.put("actor",actor);event.put("occurredAt",java.time.Instant.now().toString());afterCommit(()->{rabbit.convertAndSend("taskcraft.events","task."+action.toLowerCase(),event);if("created".equals(action)&&t.getAssignee()!=null){Map<String,Object> n=new LinkedHashMap<>();n.put("eventId",eventId+":assigned");n.put("type","TASK_ASSIGNED");n.put("recipient",t.getAssignee());n.put("actor",actor);n.put("title","Task assigned to you");n.put("message",t.getTitle());n.put("resourceId",t.getId());n.put("resourceType","TASK");rabbit.convertAndSend("taskcraft.events","notification.task.assigned",n);}});}
 private void afterCommit(Runnable r){if(TransactionSynchronizationManager.isSynchronizationActive())TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronizationAdapter(){@Override public void afterCommit(){r.run();}});else r.run();}
}
